<script setup lang="ts">
/**
 * A stored rich-text document drawn through the vocabulary (`design/components/rich-text-content.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/rich-text-content.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, provide, ref, useTemplateRef, watch } from 'vue'

import {
  RICH_TEXT_STOP,
  agentMember,
  agentPress,
  enterToolbar,
  followSelectionBar,
  holdToolbarEscape,
  mapRichTextSelection,
  placeSelectionBar,
  richTextAnnotations,
  richTextDrawing,
  richTextKeyedAnnotation,
  richTextPressedAnnotation,
  richTextSelectionBox,
  serializeRichText,
  slotDraws,
  slotNode,
  syncToolbarStop,
  toolbarFocusIn,
  toolbarFocusOut,
  toolbarKeydown,
  toolbarPress,
  toolbarStop,
  useListening,
  useTrackedSlots,
  type RichTextDocument,
  type RichTextEntity,
  type RichTextRange,
} from '@polymorph/vue'
import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/structure/rich-text-content.module.css'
import selectionBar from '@polymorph/recipes/controls/selection-bar.module.css'
import RichTextContentBlocks from './RichTextContentBlocks.vue'

export type RichTextContentSize = NonNullable<RichTextContentProps['size']>

export interface RichTextContentSelection {
  range: RichTextRange
  text: string
}

export interface RichTextContentMessages {
  selectionBar?: string
  selectionBarReady?: string
}

export interface RichTextContentProps {
  /**
   * The drawn annotation that is active, such as the thread the app shows.
   */
  activeAnnotation?: string
  /**
   * The annotations drawn. Default: every one the document holds.
   */
  annotations?: string[]
  /**
   * The page level the document's level 1 heading is drawn at. Each deeper level adds one, up to
   * 4. Default 2, one level under the page's title.
   */
  headingLevel?: 2 | 3 | 4
  /**
   * The selection bar's words, in the app's language.
   */
  messages?: RichTextContentMessages
  /**
   * The body text step (Text's `sm` or `md`), which does not change the heading scale.
   */
  size?: 'sm' | 'md'
  /**
   * The stored document. Any JSON is read as far as it can be; what is not a document draws
   * nothing.
   */
  value: RichTextDocument
}

defineOptions({ name: 'RichTextContent', inheritAttrs: false })

const props = withDefaults(defineProps<RichTextContentProps>(), { size: 'md' })
const emit = defineEmits<{ annotationSelect: [id: string]; navigate: [href: string] }>()
const callerSlots = defineSlots<{
  entity?: (props: RichTextEntity) => unknown
  selectionActions?: (props: RichTextContentSelection) => unknown
}>()
const slots = useTrackedSlots(callerSlots)
const listening = useListening()
const selected = ref({
  now: null as { range: RichTextRange; text: string; key: string } | null,
  last: null as { range: RichTextRange; text: string; key: string } | null,
})
const selecting = ref(false)
const dismissed = ref(null as string | null)
const barFocus = ref(false)
const said = ref({ text: '', at: 0 })
const barHeard = ref(false)
const bar = useTemplateRef<HTMLElement>('bar')
const root = useTemplateRef<HTMLElement>('root')
const status = useTemplateRef<HTMLElement>('status')
const held = computed(() => ({
  range: null as Range | null,
  cameFrom: null as HTMLElement | null,
  restoring: false,
}))
const say = computed(() => ({
  selectionBar: props.messages?.selectionBar ?? 'Selection',
  selectionBarReady:
    props.messages?.selectionBarReady ?? 'Controls for the selection are available: Alt+F10',
}))
const pressable = computed(() => listening.annotationSelect)
const routes = computed(() => listening.navigate)
const navigate = computed(() => (href: string) => emit('navigate', href))
const entityNode = computed(() => (drawn: RichTextEntity) => slotNode(slots.entity, drawn))
const mapped = computed(() => !!slots.selectionActions)
const appDraws = computed(() => (drawn: RichTextEntity) => slotDraws(slots.entity, drawn))
const drawing = computed(() =>
  richTextDrawing(props.value, {
    headingLevel: props.headingLevel,
    annotations: props.annotations,
    activeAnnotation: props.activeAnnotation,
    pressable: pressable.value,
    positions: mapped.value,
    appDraws: appDraws.value,
  }),
)
const drawn = computed(
  () => (id: string) => props.annotations === undefined || props.annotations.includes(id),
)
const offering = computed(() => mapped.value && !drawing.value.empty)
const docKey = computed(() => (offering.value ? serializeRichText(drawing.value.value) : ''))
const shown = computed(() => selected.value.now ?? (barFocus.value ? selected.value.last : null))
const barOpen = computed(
  () =>
    offering.value &&
    shown.value !== null &&
    !selecting.value &&
    dismissed.value !== shown.value.key,
)
const content = computed(() => selected.value.now ?? selected.value.last)
const announce = computed(() => (words: string) => {
  said.value = { text: words, at: said.value.at + 1 }
})
const outside = computed(
  () =>
    (node: Node): Element | null =>
      [bar.value, status.value].find((part) => part?.contains(node) === true) ?? null,
)
const updateSelection = computed(() => () => {
  const found = root.value
    ? mapRichTextSelection(root.value, outside.value, drawing.value.value)
    : null
  if (found !== null) held.value.range = found.dom
  // A dismissal holds for one selection: once it collapses, the next one brings the bar back.
  else dismissed.value = null
  if (found === null) {
    if (selected.value.now !== null) selected.value = { now: null, last: selected.value.last }
    return
  }
  if (selected.value.now?.key === found.key && selected.value.now.text === found.text) return
  const mapping = { range: found.range, text: found.text, key: found.key }
  selected.value = { now: mapping, last: mapping }
})
const followSelection = computed(() => (element: HTMLElement) => {
  const page = element.ownerDocument
  const update = () => updateSelection.value()
  page.addEventListener('selectionchange', update)
  return () => page.removeEventListener('selectionchange', update)
})
const releaseSelecting = computed(() => (element: HTMLElement) => {
  const view = element.ownerDocument.defaultView
  const release = () => {
    selecting.value = false
  }
  view?.addEventListener('pointerup', release, true)
  view?.addEventListener('pointercancel', release, true)
  return () => {
    view?.removeEventListener('pointerup', release, true)
    view?.removeEventListener('pointercancel', release, true)
  }
})
const holdKeys = computed(() => (element: HTMLElement) => {
  const view = element.ownerDocument.defaultView
  const keys = (event: KeyboardEvent) => {
    const target = event.target
    if (event.isComposing || !(target instanceof Node)) return
    if (bar.value?.contains(target) === true) return
    const page = element.ownerDocument
    if (target !== page.body && target !== page.documentElement && !element.contains(target)) return
    if (event.key === 'Escape') {
      event.preventDefault()
      if (shown.value !== null) dismissed.value = shown.value.key
    } else if (event.key === 'F10' && event.altKey) {
      event.preventDefault()
      enterToolbar(bar.value, barStops.value)
    }
  }
  view?.addEventListener('keydown', keys, true)
  return () => view?.removeEventListener('keydown', keys, true)
})
const restoreSelection = computed(() => () => {
  const range = held.value.range
  const selection = root.value?.ownerDocument.getSelection()
  if (range === null || selection === null || selection === undefined || !selection.isCollapsed)
    return
  selection.removeAllRanges()
  selection.addRange(range)
})
const leaveBar = computed(() => () => {
  if (shown.value !== null) dismissed.value = shown.value.key
  held.value.restoring = true
  restoreSelection.value()
})
const giveFocusBack = computed(() => () => {
  const to = held.value.cameFrom
  held.value.cameFrom = null
  const active = bar.value?.ownerDocument.activeElement
  if (to !== null && to.isConnected && bar.value?.contains(to) !== true)
    to.focus({ preventScroll: true })
  else if (active instanceof HTMLElement && bar.value?.contains(active) === true) active.blur()
  if (held.value.restoring) restoreSelection.value()
  held.value.restoring = false
})
const barLeave = computed(() => (event: FocusEvent) => {
  const to = event.relatedTarget
  if (to instanceof Node && (event.currentTarget as HTMLElement).contains(to)) return
  barFocus.value = false
  // A leaving bar is inert, and a browser that moves focus off it does so here.
  if (bar.value?.inert === true) giveFocusBack.value()
})
const cameFrom = computed(() => (event: FocusEvent) => {
  const from = event.relatedTarget
  if (from instanceof HTMLElement && bar.value?.contains(from) === true) return
  held.value.cameFrom = from instanceof HTMLElement ? from : null
})
const documentChanged = computed(() => () => {
  selected.value = { now: null, last: null }
  held.value.range = null
  const selection = root.value?.ownerDocument.getSelection()
  if (
    root.value === null ||
    root.value === undefined ||
    selection === null ||
    selection === undefined
  )
    return
  if (selection.rangeCount === 0 || selection.isCollapsed) return
  const range = selection.getRangeAt(0)
  if (root.value.contains(range.startContainer) || root.value.contains(range.endContainer))
    selection.collapseToEnd()
})
const measure = computed(() => () => {
  const selection = root.value?.ownerDocument.getSelection()
  if (root.value && selection && selection.rangeCount > 0) {
    const range = selection.getRangeAt(0)
    if (!range.collapsed && root.value.contains(range.commonAncestorContainer))
      return richTextSelectionBox(range)
  }
  return held.value.range === null ? null : richTextSelectionBox(held.value.range)
})
const placeBar = computed(() => () => placeSelectionBar(bar.value, measure.value()))
const barStops = computed(() => toolbarStop())
const holdEscapeIn = computed(() => (element: HTMLElement) => {
  const view = element.ownerDocument.defaultView
  return view === null ? () => {} : holdToolbarEscape(view, () => bar.value)
})
const pressed = computed(() => (event: MouseEvent) => {
  const id = richTextPressedAnnotation(
    event.currentTarget as Element,
    event.target,
    event.detail,
    bar.value,
  )
  if (id !== null) emit('annotationSelect', id)
})
const keyed = computed(() => (event: KeyboardEvent, phase: 'down' | 'up') => {
  const id = richTextKeyedAnnotation(event, phase)
  if (id !== null) emit('annotationSelect', id)
})
const pressDown = computed(() => (event: PointerEvent) => {
  if (!(event.target instanceof Node) || bar.value?.contains(event.target) !== true)
    selecting.value = true
})
const barPresent = usePresence(() => barOpen.value, bar)
provide('polymorph:RichTextContent', {
  get size() {
    return props.size
  },
  get pressable() {
    return pressable.value
  },
  get routes() {
    return routes.value
  },
  get navigate() {
    return navigate.value
  },
  get entityNode() {
    return entityNode.value
  },
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = offering.value && root.value ? followSelection.value(root.value) : () => {}
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
watch(() => offering.value, effect1, { flush: 'post' })
onBeforeUnmount(() => release1?.())
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = selecting.value && root.value ? releaseSelecting.value(root.value) : () => {}
  release2 = () => {
    ran()
  }
}
onMounted(effect2)
watch(() => selecting.value, effect2, { flush: 'post' })
onBeforeUnmount(() => release2?.())
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = barOpen.value && root.value ? holdKeys.value(root.value) : () => {}
  release3 = () => {
    ran()
  }
}
onMounted(effect3)
watch(() => barOpen.value, effect3, { flush: 'post' })
onBeforeUnmount(() => release3?.())
const effect4 = () => {
  documentChanged.value()
}
watch(() => docKey.value, effect4, { flush: 'post' })
const effect5 = () => {
  !barOpen.value &&
    bar.value?.contains(bar.value.ownerDocument.activeElement) === true &&
    giveFocusBack.value()
}
watch(() => barOpen.value, effect5, { flush: 'post' })
const effect6 = () => {
  barOpen.value &&
    !barHeard.value &&
    ((barHeard.value = true), announce.value(say.value.selectionBarReady))
}
onMounted(effect6)
watch(() => barOpen.value, effect6, { flush: 'post' })
let release7: (() => void) | undefined
const effect7 = () => {
  release7?.()
  const run = () => {
    syncToolbarStop(bar.value, barStops.value)
  }
  const mutation = typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(run)
  for (const element of [bar.value])
    if (element)
      mutation?.observe(element, {
        childList: true,
        characterData: true,
        subtree: true,
        attributeFilter: ['disabled', 'aria-disabled', 'hidden', 'inert'],
      })
  release7 = () => {
    mutation?.disconnect()
  }
  run()
}
onMounted(effect7)
watch(() => barPresent.value, effect7, { flush: 'post' })
onBeforeUnmount(() => release7?.())
let release8: (() => void) | undefined
const effect8 = () => {
  release8?.()
  const ran = barPresent.value && bar.value ? holdEscapeIn.value(bar.value) : () => {}
  release8 = () => {
    ran()
  }
}
onMounted(effect8)
watch(() => barPresent.value, effect8, { flush: 'post' })
onBeforeUnmount(() => release8?.())
const effect9 = () => {
  barOpen.value && placeBar.value()
}
onMounted(effect9)
watch(() => [barOpen.value, selected.value], effect9, { flush: 'post' })
let release10: (() => void) | undefined
const effect10 = () => {
  release10?.()
  const ran = barOpen.value && bar.value ? followSelectionBar(bar.value, placeBar.value) : () => {}
  release10 = () => {
    ran()
  }
}
onMounted(effect10)
watch(() => barOpen.value, effect10, { flush: 'post' })
onBeforeUnmount(() => release10?.())
let release11: (() => void) | undefined
const effect11 = () => {
  release11?.()
  const ran = !listening.annotationSelect
    ? () => {}
    : agentMember({
        member: 'RichTextContent',
        element: () => root.value,
        state: () => ({
          annotations: richTextAnnotations(drawing.value.value)
            .filter((annotation) => drawn.value(annotation.id))
            .map((annotation) => ({
              id: annotation.id,
              label: annotation.text,
              ...(drawing.value.stops.includes(annotation.id) ? {} : { disabled: true }),
            })),
          active: richTextAnnotations(drawing.value.value).some(
            (annotation) => drawn.value(annotation.id) && annotation.id === props.activeAnnotation,
          )
            ? (props.activeAnnotation ?? null)
            : null,
        }),
        actions: {
          select: {
            argument: 'id',
            run: (value) =>
              (() => {
                const stop = Array.from(root.value?.querySelectorAll(RICH_TEXT_STOP) ?? []).find(
                  (element) => element.getAttribute('data-annotation-id') === value,
                )
                if (stop === undefined)
                  throw new Error('That annotation has no highlight to press.')
                agentPress(stop)
              })(),
          },
        },
      })
  release11 = () => {
    ran()
  }
}
onMounted(effect11)
onBeforeUnmount(() => release11?.())
</script>

<template>
  <div
    ref="root"
    :class="styles.root"
    :data-size="size"
    :data-empty="drawing.empty ? '' : undefined"
    data-member="rich-text-content"
    @click="pressable && pressed($event)"
    @keydown="pressable && keyed($event, 'down')"
    @keyup="pressable && keyed($event, 'up')"
    @pointerdown="offering && pressDown($event)"
  >
    <RichTextContentBlocks v-if="!drawing.empty" :blocks="drawing.blocks" />
    <!-- selection bar -->
    <div
      v-if="offering && barPresent"
      ref="bar"
      :class="selectionBar.bar"
      role="toolbar"
      :aria-label="say.selectionBar"
      :data-state="!barOpen ? 'closed' : undefined"
      :inert="!barOpen ? true : undefined"
      @keydown="toolbarKeydown($event.currentTarget as HTMLElement, $event, barStops, leaveBar)"
      @focusin="
        (toolbarFocusIn($event.currentTarget as HTMLElement, $event, barStops), (barFocus = true))
      "
      @focusout="
        (toolbarFocusOut($event.currentTarget as HTMLElement, $event, barStops), barLeave($event))
      "
      @mousedown="toolbarPress($event.currentTarget as HTMLElement, $event)"
    >
      <!-- actions -->
      <div :class="styles.actions" @focusin="cameFrom($event)">
        <template v-if="content !== null">
          <slot name="selectionActions" :range="content.range" :text="content.text" />
        </template>
      </div>
    </div>
    <!-- status -->
    <div v-if="offering" ref="status" :class="styles.status" role="status" aria-live="polite">
      <span v-if="said.text !== ''" :key="said.at">
        {{ said.text }}
      </span>
    </div>
  </div>
</template>
